/* Generated by Trae Work */
/* 课表：引擎 A（自考 · 考期倒排 + 选科）与引擎 B（考研 · 阶段 + 每日时间权重） */
"use strict";
(function () {
  const SLOTS = ["morning", "afternoon", "evening"];
  const SLOT_NAMES = { morning: "上午", afternoon: "下午", evening: "晚上" };
  /* 每个时段的起始钟点；结束钟点 = 起始 + duration_min */
  const SLOT_TIMES = { morning: "08:30", afternoon: "14:30", evening: "19:00" };
  /* 排课起始日：用户指定从 2026-11-03 开始，之前不生成任何课表块 */
  const SCHEDULE_START = "2026-11-03";
  const WEEKDAYS = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"];
  const KAoyanTarget = SITE_DATA.countdown.kaoyan_target; // 2027-12-19

  function slotRange(slot, durMin) {
    const [hh, mm] = SLOT_TIMES[slot].split(":").map(Number);
    const fmt = t => `${String(Math.floor(t / 60)).padStart(2, "0")}:${String(t % 60).padStart(2, "0")}`;
    return `${SLOT_TIMES[slot]}–${fmt(hh * 60 + mm + durMin)}`;
  }

  /* ================= 引擎 B：阶段判定 ================= */
  function kaoyanStage(dateISO) {
    const now = new Date(dateISO + "T00:00:00");
    const tgt = new Date(KAoyanTarget + "T00:00:00");
    const months = (tgt.getFullYear() - now.getFullYear()) * 12 + (tgt.getMonth() - now.getMonth());
    if (months > 6) return "basic";        // 当前至约 2027-06：准备期/基础期
    if (months > 3) return "enhance";      // 约 2027-07—09：强化期
    return "sprint";                        // 约 2027-10 至考前：冲刺期
  }

  /* ================= 引擎 A：自考选科 ================= */
  function zkSelectableCourses() {
    return SITE_DATA.zikao.courses.filter(c => c.chapters || c.reference_chapters);
  }
  function zkSelected() {
    return Store.get("zk_subjects", []);
  }
  function zkWeeksUntilNextExam() {
    const ev = nextZikaoDate();
    if (!ev) return null;
    return Math.max(0, Math.floor(daysUntil(ev.date_start) / 7));
  }

  /* ================= 块生成（确定性，周为单位滚动） ================= */
  function mulberry(seed) {
    return function () {
      seed |= 0; seed = (seed + 0x6D2B79F5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function hashStr(s) { let h = 0; for (let i = 0; i < s.length; i++) { h = (h * 31 + s.charCodeAt(i)) | 0; } return h; }

  function zikaoBlocksForWeek(weekStart /*Date Mon*/, weekIdx) {
    const sel = zkSelected();
    if (sel.length < 2) return [];
    const weeks = zkWeeksUntilNextExam();
    /* 距考节奏 */
    let blocksPerSubject;
    let mode;
    if (weeks === null) { mode = "no_exam"; blocksPerSubject = 1; }        // 考期待公布 → 基础节奏
    else if (weeks >= 12) { mode = "far"; blocksPerSubject = 1; }          // 每周 3—4 块（2 门课×1—2）
    else if (weeks >= 6) { mode = "mid"; blocksPerSubject = 2; }           // 每周 4—5 块：章节 + 真题组合
    else if (weeks >= 2) { mode = "near"; blocksPerSubject = 2; }          // 每周 5—6 块：真题限时 + 错题
    else { mode = "final"; blocksPerSubject = 1; }                         // 2 周内：只排错题回顾与真题二次练习
    /* 用户确认减负：skip 提示确认后，下周自考块数减 1 */
    const todayMon = fmtDate(mondayOf(new Date()));
    const weekKey = fmtDate(weekStart);
    let reduced = Store.get("reduced_week_" + weekKey, false);
    if (!reduced && Store.get("reduced_next_week", false) && weekKey > todayMon) {
      reduced = true;
      Store.set("reduced_week_" + weekKey, true);
      Store.del("reduced_next_week");
    }
    if (reduced && blocksPerSubject > 1) blocksPerSubject -= 1;

    const courses = sel.map(code => SITE_DATA.zikao.courses.find(c => c.code === code)).filter(Boolean);
    const blocks = [];
    const slotPlan = [[0, "evening"], [2, "evening"], [4, "afternoon"]]; // 周一/三/六晚? 简单确定性分布
    courses.forEach((c, ci) => {
      const chapters = c.has_syllabus && c.chapters ? c.chapters : (c.reference_chapters ? c.reference_chapters.chapters : null);
      if (!chapters || chapters.length === 0) return; // 无公开结构信息的科目不生成课表块
      const hasSyllabus = c.has_syllabus && c.chapters;
      const sourceUrl = hasSyllabus ? c.syllabus_url : c.reference_chapters.source_url;
      const basis = hasSyllabus ? "syllabus_chapter" : "reference_chapter";
      const rand = mulberry(hashStr(fmtDate(weekStart) + c.code));
      for (let b = 0; b < blocksPerSubject; b++) {
        const [wd, slot] = slotPlan[(ci * 2 + b) % slotPlan.length];
        if (isBlankHalfDay(weekStart, wd, slot)) continue;
        const chIdx = (weekIdx * blocksPerSubject + b) % chapters.length;
        let title, sb = basis;
        if (mode === "final") {
          title = `${c.code} ${c.name}：错题本回顾（仅限已收录内容）`;
          sb = "past_paper";
        } else if (mode === "near" && b === 1) {
          title = `${c.code} ${c.name}：已收录真题/回忆版限时练习（本站当前未收录该科目真题，自动降级为章节回顾）`;
          title = `${c.code} ${c.name}：${chapters[chIdx]}（章节回顾）`;
          sb = basis;
        } else if (mode === "mid" && b === 1) {
          title = `${c.code} ${c.name}：${chapters[chIdx]}（章节 + 对应真题组合；真题未收录时以章节练习替代）`;
        } else {
          title = `${c.code} ${c.name}：${chapters[chIdx]}`;
        }
        blocks.push({
          id: `zk-${c.code}-w${weekIdx}-b${b}`,
          date: fmtDate(new Date(weekStart.getTime() + wd * 86400000)),
          track: "zikao", subject: c.code, content_title: title,
          source_basis: sb, source_url: sourceUrl,
          duration_min: 90, time_slot: slot, status: "pending",
          _wd: wd
        });
      }
    });
    return blocks;
  }

  function isBlankHalfDay(weekStart, weekdayIdx, slot) {
    const blank = Store.get("blank_half_day", { weekday: 5, slot: "afternoon" });
    return blank && blank.weekday === weekdayIdx && blank.slot === slot;
  }

  const M2_TOPICS = ["高等数学（考试范围说明：高数约 78%，线代约 22%）", "线性代数（考试范围说明：不考概率论与数理统计）"];
  const M2_SUB = ["一元函数微分学", "一元函数积分学", "多元函数微积分（大纲范围内）", "常微分方程", "行列式与矩阵", "向量组与线性方程组", "特征值与二次型"];
  const E2_SUB = ["完形填空（20 题 × 0.5 分）", "传统阅读 4 篇（20 题 × 2 分）", "新题型（5 题 × 2 分）", "翻译（约 150 词段落，15 分）", "写作（15 分）"];

  function kaoyanBlocksForDate(dateISO, stage) {
    const d = new Date(dateISO + "T00:00:00");
    const wd = (d.getDay() + 6) % 7; // 0=Mon
    const rand = mulberry(hashStr(dateISO));
    const blocks = [];
    const outlineUrl = SITE_DATA.kaoyan.exam408.syllabus_source.source_url;
    const dsSubs = SITE_DATA.kaoyan.exam408.subjects;
    const paperUrl = SITE_DATA.kaoyan.papers.length ? SITE_DATA.kaoyan.papers[0].source_url : outlineUrl;

    /* 每日时间权重（基础期），按比例压缩而非取消任何一科 */
    let weights = {
      "408-ds": [120, 150], "408-org": [120, 150], "数二": [180, 210], "英二": [90, 120]
    };
    let plan;
    if (stage === "basic") {
      plan = [
        { subject: "数二", slot: "morning", min: [90, 120] },
        { subject: "408-ds", slot: "afternoon", min: [90, 120] },
        { subject: "英二", slot: "evening", min: [90, 120] },
        { subject: "408-org", slot: "evening", min: [60, 90] }
      ];
    } else if (stage === "enhance") {
      plan = [
        { subject: "408-ds", slot: "morning", min: [120, 150] },   // 上午安排逻辑推理内容
        { subject: "数二", slot: "afternoon", min: [120, 150] },   // 增加整套题
        { subject: "英二", slot: "evening", min: [90, 120] },
        { subject: "408-os", slot: "evening", min: [60, 90] }
      ];
    } else {
      plan = [
        { subject: "408-ds", slot: "morning", min: [120, 150] },   // 完整真题模拟 / 错题回顾
        { subject: "数二", slot: "afternoon", min: [90, 120] },    // 保持手感
        { subject: "英二", slot: "evening", min: [60, 90] }
      ];
    }

    /* 周日白天保留：整周复盘/弹性缓冲不排新块（弹性） */
    const isSunday = wd === 6;
    plan.forEach((p, pi) => {
      if (isBlankHalfDay(new Date(dateISO + "T00:00:00"), wd, p.slot)) return;
      if (isSunday && p.slot !== "evening") return;
      const dur = p.min[0] + Math.floor(rand() * (p.min[1] - p.min[0] + 1));
      const subjectNameMap = { "数二": "数学（二）", "英二": "英语（二）" };
      let title, sb = "outline_section", url = outlineUrl;
      if (p.subject.startsWith("408-")) {
        const sub = dsSubs.find(s => s.code === p.subject);
        const ch = sub.chapters[Math.floor(rand() * sub.chapters.length)];
        if (stage === "sprint") {
          title = `408 · ${sub.name}：历年真题完整模拟与错题回顾（来源仓库 2009—2026）`;
          sb = "past_paper"; url = paperUrl;
        } else if (stage === "enhance" && pi === 0) {
          title = `408 · ${sub.name}：${ch.title}（按板块刷真题：${ch.subs[0]} 等）`;
        } else {
          title = `408 · ${sub.name}：大纲章节「${ch.title}」`;
        }
      } else if (p.subject === "数二") {
        const t = M2_SUB[Math.floor(rand() * M2_SUB.length)];
        title = stage === "enhance" ? `数学（二）：${t} + 整套题训练` : `数学（二）：${t}`;
      } else {
        const t = E2_SUB[Math.floor(rand() * E2_SUB.length)];
        title = stage === "enhance" ? `英语（二）：${t}（依次攻克完形、新题型、翻译）` : `英语（二）：${t}（单词 + 精读）`;
      }
      blocks.push({
        id: `ky-${dateISO}-${p.slot}-${p.subject}`,
        date: dateISO, track: "kaoyan", subject: p.subject, content_title: title,
        source_basis: sb, source_url: url, duration_min: dur,
        time_slot: p.slot, status: "pending"
      });
    });
    /* 自考临近且仍有未通过科目（用户已选科）→ 保持自考块存在；否则冲刺期降为维持性错题回顾 */
    return blocks;
  }

  /* ================= 周生成 + 覆盖应用 ================= */
  function mondayOf(date) {
    const d = new Date(date); d.setHours(0, 0, 0, 0);
    const shift = (d.getDay() + 6) % 7;
    d.setDate(d.getDate() - shift);
    return d;
  }
  function generateWeek(weekStart) {
    const weekIdx = Math.round((weekStart - mondayOf(new Date(SCHEDULE_START + "T00:00:00"))) / (7 * 86400000));
    const todayISO = fmtDate(new Date());
    const stage = kaoyanStage(todayISO);
    let blocks = [];
    /* 自考块：考期内 6 周以上才铺满；冲刺期如自考临近且已选科则保留 */
    const zk = zikaoBlocksForWeek(weekStart, weekIdx);
    blocks = blocks.concat(zk);
    /* 考研块：逐日 */
    for (let i = 0; i < 7; i++) {
      const day = new Date(weekStart.getTime() + i * 86400000);
      blocks = blocks.concat(kaoyanBlocksForDate(fmtDate(day), stage));
    }
    /* 排课起始日过滤：2026-11-03 之前不排课 */
    blocks = blocks.filter(b => b.date >= SCHEDULE_START);
    /* 应用用户覆盖（状态/移动） */
    const ov = Store.get("block_overrides", {});
    const mv = Store.get("block_moves", {});
    blocks.forEach(b => {
      if (ov[b.id]) { b.status = ov[b.id].status; if (ov[b.id].reason) b.skip_reason = ov[b.id].reason; }
      if (mv[b.id] && mv[b.id].date) {
        /* 仅允许同周内拖拽 */
        const newDate = new Date(mv[b.id].date + "T00:00:00");
        if (newDate >= weekStart && newDate < new Date(weekStart.getTime() + 7 * 86400000)) {
          b.date = mv[b.id].date;
          if (mv[b.id].time_slot) b.time_slot = mv[b.id].time_slot;
        }
      }
    });
    return blocks;
  }

  /* ================= 渲染 ================= */
  let currentDate = fmtDate(new Date());
  let weekMode = false;

  function render() {
    const view = document.getElementById("sch-view");
    const d = new Date(currentDate + "T00:00:00");
    const weekStart = mondayOf(d);
    const weekIdx = Math.round((weekStart - mondayOf(new Date(SCHEDULE_START + "T00:00:00"))) / (7 * 86400000));
    const blocks = generateWeek(weekStart).filter(b => weekMode || b.date === currentDate);
    const sel = zkSelected();
    const weeks = zkWeeksUntilNextExam();
    const stage = kaoyanStage(fmtDate(new Date()));

    let head = `<div class="sched-day-title">${weekMode
      ? `本周概览（${fmtDate(weekStart)} 起）`
      : `${d.getMonth() + 1} 月 ${d.getDate()} 日 · ${WEEKDAYS[(d.getDay() + 6) % 7]}`}</div>
      <p class="desc">考研阶段判定：<strong>${stage === "basic" ? "准备期/基础期" : stage === "enhance" ? "强化期" : "冲刺期"}</strong>（距 ${KAoyanTarget}，预计日期）
      · 自考下次考期：<strong>${weeks === null ? "待官方公布（暂按基础节奏排课）" : `距考 ${weeks} 周`}</strong>
      · 已选自考科目：${sel.length ? sel.join("、") : "<strong>未选择</strong>"}</p>`;

    if (sel.length < 2) {
      head += `<div class="notice ref"><strong>请先在下方设置中选择本次考期准备报考的 2—4 门。</strong>未选择时，自考引擎不生成全科课表，只显示本引导提示。</div>`;
    }
    if (currentDate < SCHEDULE_START) {
      head += `<div class="notice info">排课起始日为 <strong>${SCHEDULE_START}</strong>，此前不生成课表块。点“下一天”到 ${SCHEDULE_START} 查看首日安排。</div>`;
    }
    if (weeks === null) {
      head += `<div class="notice info">下一次自考考期待官方公布，倒计时与倒排节奏暂不可用，自考块按基础节奏生成。</div>`;
    }

    let body = "";
    if (weekMode) {
      const cols = [...Array(7)].map((_, i) => {
        const day = new Date(weekStart.getTime() + i * 86400000);
        const iso = fmtDate(day);
        const dayBlocks = blocks.filter(b => b.date === iso).sort((a, b) => SLOTS.indexOf(a.time_slot) - SLOTS.indexOf(b.time_slot));
        return `<div class="week-col${iso === currentDate ? " today" : ""}" data-date="${iso}">
          <h5>${WEEKDAYS[i]}<br><span style="font-weight:400">${iso.slice(5)}</span></h5>
          ${dayBlocks.map(b => miniBlockHtml(b)).join("") || `<div style="font-size:11.5px;color:var(--muted);text-align:center;">—</div>`}
        </div>`;
      }).join("");
      body = `<div class="week-grid">${cols}</div><p class="desc" style="margin-top:10px;">支持同周内拖拽调整（拖动块到其他日期列）；用户覆盖存 localStorage，不覆盖引擎原始建议。</p>`;
    } else {
      body = SLOTS.map(slot => {
        const bs = blocks.filter(b => b.time_slot === slot).sort((a, b) => a.track.localeCompare(b.track));
        return `<div class="slot-group"><h4>${SLOT_NAMES[slot]}</h4>${
          bs.length ? bs.map(b => blockHtml(b)).join("") : `<div class="notice empty">${isBlankHalfDay(new Date(currentDate + "T00:00:00"), (d.getDay() + 6) % 7, slot) ? "你设置的每周空白半日，引擎不在该时段排块。" : "该时段暂无课表块。"}</div>`
        }</div>`;
      }).join("");
    }

    view.innerHTML = head + body;
    bindBlockActions(view);
    if (weekMode) bindDnD(view);
    renderSkipNudge();
    renderSettings();
  }

  function blockSrc(b) {
    return `<div class="b-src src">source_basis：${b.source_basis} · 来源：<a href="${b.source_url}" target="_blank" rel="noopener">${b.source_url}</a></div>`;
  }
  function blockHtml(b) {
    return `<div class="block ${b.track} ${b.status}" draggable="true" data-id="${b.id}" data-date="${b.date}">
      <div>
        <div class="b-title">${badge(b.track)} ${b.content_title}</div>
        <div class="b-meta"><strong>${slotRange(b.time_slot, b.duration_min)}</strong> · ${subjectName(b.subject)} · ${b.duration_min} 分钟 · ${b.status === "done" ? "已完成" : b.status === "skipped" ? `已跳过${b.skip_reason ? "（" + b.skip_reason + "）" : ""}` : "待完成"}</div>
        ${blockSrc(b)}
      </div>
      <div class="block-actions">
        ${b.status !== "done" ? `<button data-act="done" data-id="${b.id}">完成</button>` : ""}
        ${b.status !== "skipped" ? `<button data-act="skip" data-id="${b.id}">跳过</button>` : `<button data-act="reset" data-id="${b.id}">撤销</button>`}
      </div>
    </div>`;
  }
  function miniBlockHtml(b) {
    return `<div class="mini-block ${b.track} ${b.status}" draggable="true" data-id="${b.id}" data-date="${b.date}" title="${slotRange(b.time_slot, b.duration_min)} ${b.content_title}">
      <div class="mb-t">${SLOT_NAMES[b.time_slot]} ${SLOT_TIMES[b.time_slot]} ${subjectName(b.subject)}</div>
      <div class="b-meta">${slotRange(b.time_slot, b.duration_min)} · ${b.status === "done" ? "✓" : b.status === "skipped" ? "跳过" : ""}</div>
    </div>`;
  }

  function bindBlockActions(root) {
    root.querySelectorAll("button[data-act]").forEach(btn => {
      btn.addEventListener("click", () => {
        const id = btn.dataset.id, act = btn.dataset.act;
        const ov = Store.get("block_overrides", {});
        if (act === "done") ov[id] = { status: "done" };
        else if (act === "skip") {
          const reason = prompt("跳过原因（可选，直接确定留空）：") || "";
          ov[id] = { status: "skipped", reason };
        } else if (act === "reset") delete ov[id];
        Store.set("block_overrides", ov);
        render();
      });
    });
  }

  function bindDnD(root) {
    let dragId = null;
    root.querySelectorAll("[draggable=true]").forEach(el => {
      el.addEventListener("dragstart", e => { dragId = el.dataset.id; });
      el.addEventListener("dragend", () => { dragId = null; root.querySelectorAll(".week-col").forEach(c => c.classList.remove("drag-over")); });
    });
    root.querySelectorAll(".week-col").forEach(col => {
      col.addEventListener("dragover", e => { e.preventDefault(); col.classList.add("drag-over"); });
      col.addEventListener("dragleave", () => col.classList.remove("drag-over"));
      col.addEventListener("drop", e => {
        e.preventDefault(); col.classList.remove("drag-over");
        if (!dragId) return;
        if (col.dataset.date < SCHEDULE_START) { alert(`排课起始日为 ${SCHEDULE_START}，不能将块移动到该日期之前。`); return; }
        const mv = Store.get("block_moves", {});
        mv[dragId] = { date: col.dataset.date };
        Store.set("block_moves", mv);
        render();
      });
    });
  }

  /* ================= 连续 3 天跳过提示（需用户确认，不静默自动调整） ================= */
  function renderSkipNudge() {
    const box = document.getElementById("skip-nudge-box");
    const nudge = document.getElementById("skip-nudge");
    const ov = Store.get("block_overrides", {});
    const days = [...Array(3)].map((_, i) => {
      const d = new Date(); d.setDate(d.getDate() - i);
      return fmtDate(d);
    });
    const skipped3 = days.every(day => Object.values(ov).some(o => o.status === "skipped") &&
      /* 该天存在被跳过的块：通过块 id 无法直接知道日期，改为检查 overrides 中带有该天生成的块 */
      Object.keys(ov).some(id => ov[id].status === "skipped" && id.includes(day)));
    const ack = Store.get("skip_nudge_ack_" + days[0], false);
    if (skipped3 && !ack) {
      box.style.display = "";
      nudge.innerHTML = `连续 3 天有块被跳过。<strong>是否需要减少下周排课量？</strong>
        <button class="btn small" id="nudge-yes">是，下周自考块减 1、考研各科时长压缩 20%</button>
        <button class="btn small ghost" id="nudge-no">否，保持当前节奏</button>`;
      document.getElementById("nudge-yes").addEventListener("click", () => {
        Store.set("reduced_next_week", true);
        Store.set("skip_nudge_ack_" + days[0], true);
        render();
      });
      document.getElementById("nudge-no").addEventListener("click", () => {
        Store.set("skip_nudge_ack_" + days[0], true);
        render();
      });
    } else {
      box.style.display = "none";
    }
  }

  /* ================= 设置面板 ================= */
  function renderSettings() {
    const list = document.getElementById("zk-subject-list");
    const sel = zkSelected();
    const courses = zkSelectableCourses();
    if (!list.dataset.built) {
      list.innerHTML = courses.map(c => {
        const basis = c.has_syllabus ? "官方大纲" : "参考章节";
        return `<label><input type="checkbox" value="${c.code}" ${sel.includes(c.code) ? "checked" : ""}> ${c.code} ${c.name}（${basis}）</label>`;
      }).join("");
      list.addEventListener("change", () => {
        const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
        if (checked.length > 4) {
          alert("黑龙江自考每次最多报考 4 门。");
          list.querySelector(`input[value="${checked[checked.length - 1]}"]`).checked = false;
        }
      });
      list.dataset.built = "1";
    }
    document.getElementById("zk-subject-save").onclick = () => {
      const checked = [...list.querySelectorAll("input:checked")].map(i => i.value);
      if (checked.length > 0 && checked.length < 2) { alert("至少选择 2 门（每次最多 4 门）"); return; }
      Store.set("zk_subjects", checked);
      render();
    };
    const bw = document.getElementById("blank-weekday");
    if (!bw.dataset.built) {
      bw.innerHTML = WEEKDAYS.map((w, i) => `<option value="${i}">${w}</option>`).join("");
      bw.dataset.built = "1";
    }
    const blank = Store.get("blank_half_day", { weekday: 5, slot: "afternoon" });
    bw.value = blank.weekday;
    document.getElementById("blank-slot").value = blank.slot;
    document.getElementById("blank-save").onclick = () => {
      Store.set("blank_half_day", { weekday: +bw.value, slot: document.getElementById("blank-slot").value });
      render();
    };
    document.getElementById("sch-reset").onclick = () => {
      if (!confirm("清空所有课表本地记录（选科/覆盖/移动/打卡除外）？")) return;
      ["block_overrides", "block_moves"].forEach(k => Store.del(k));
      Object.keys(localStorage).filter(k => k.startsWith("heuprep:reduced_") || k.startsWith("heuprep:skip_nudge_ack_")).forEach(k => localStorage.removeItem(k));
      render();
    };
  }

  /* ================= 事件 ================= */
  document.addEventListener("DOMContentLoaded", () => {
    document.getElementById("sch-prev").addEventListener("click", () => { const d = new Date(currentDate + "T00:00:00"); d.setDate(d.getDate() - 1); currentDate = fmtDate(d); render(); });
    document.getElementById("sch-next").addEventListener("click", () => { const d = new Date(currentDate + "T00:00:00"); d.setDate(d.getDate() + 1); currentDate = fmtDate(d); render(); });
    document.getElementById("sch-today").addEventListener("click", () => { currentDate = fmtDate(new Date()); render(); });
    document.getElementById("sch-week-toggle").addEventListener("click", e => {
      weekMode = !weekMode;
      e.target.textContent = weekMode ? "切回单日视图" : "切换本周概览";
      render();
    });
    render();
  });
})();
